// spec: specs/business-cards-images.md (1.5–1.6) · кейс: .qa/tests/business-cards-images/CARDIMG-06.md
// Значки в углах окна медиа не сдвинулись после #0a2499: сердце (вверху слева), «поделиться» (рядом справа),
// бейдж просмотров «N 👁» (внизу справа). Сердце и просмотры видны вошедшему — admin (сессия ../auth/admin.json).
// Прод, только просмотр: значки не нажимаются, не-GET запросы блокируются (кроме чтения через RPC).
import { test, expect, Page } from '@playwright/test';
import { prepare, openCards, loadFirst, MEDIA } from './cards.helpers';

type Off = { l: number; t: number; r: number; b: number } | null;
type Badges = { idx: number; heart: Off; share: Off; views: Off };

async function readBadges(page: Page, n: number): Promise<Badges[]> {
  return page.locator(MEDIA).evaluateAll((els, max) => {
    const out: { idx: number; heart: Off; share: Off; views: Off }[] = [];
    els.forEach((m, idx) => {
      const M = m.getBoundingClientRect();
      if (!M.width || out.length >= max) return;
      const off = (e: Element | null | undefined) => {
        if (!e) return null;
        const b = e.getBoundingClientRect();
        return { l: b.left - M.left, t: b.top - M.top, r: M.right - b.right, b: M.bottom - b.bottom };
      };
      out.push({
        idx,
        heart: off(m.querySelector('svg.lucide-heart')?.closest('button')),
        share: off(m.querySelector('svg.lucide-share2')?.closest('button')),
        views: off(m.querySelector('span[aria-label*="צפיות"]')),
      });
    });
    return out;
  }, n);
}

const PAGES = [
  { path: '/search' as const, name: '/search' },
  { path: '/' as const, name: 'главная' },
];

for (const dev of ['@desktop', '@android']) {
  test.describe(`Значки карточек — admin ${dev}`, () => {
    test.use({ storageState: '../auth/admin.json' });

    for (const p of PAGES) {
      test(`${p.name}: сердце, «поделиться» и просмотры на прежних местах в углах окна #0a2499 ${dev} @prod-safe`, async ({ page }) => {
        await prepare(page);
        await openCards(page, p.path);
        await expect(page.locator('header').getByText('התחברות'), 'admin вошёл').toHaveCount(0);
        await loadFirst(page, 12);
        const rows = await readBadges(page, 12);
        expect(rows.length, `${p.name}: есть карточки`).toBeGreaterThan(0);

        for (const r of rows) {
          const at = `${p.name}, карточка ${r.idx}`;
          expect(r.heart, `${at}: есть сердце`).not.toBeNull();
          expect(r.share, `${at}: есть «поделиться»`).not.toBeNull();
          // Сердце — верхний левый угол (замер 13/13 px).
          expect(r.heart!.l, `${at}: сердце у левого края`).toBeGreaterThanOrEqual(0);
          expect(r.heart!.l, `${at}: сердце у левого края`).toBeLessThanOrEqual(20);
          expect(r.heart!.t, `${at}: сердце у верхнего края`).toBeGreaterThanOrEqual(0);
          expect(r.heart!.t, `${at}: сердце у верхнего края`).toBeLessThanOrEqual(20);
          // «Поделиться» — справа от сердца, в верхнем ряду (замер 58/15 px).
          expect(r.share!.t, `${at}: «поделиться» у верхнего края`).toBeGreaterThanOrEqual(0);
          expect(r.share!.t, `${at}: «поделиться» у верхнего края`).toBeLessThanOrEqual(22);
          expect(r.share!.l, `${at}: «поделиться» рядом с сердцем`).toBeGreaterThanOrEqual(40);
          expect(r.share!.l, `${at}: «поделиться» рядом с сердцем`).toBeLessThanOrEqual(80);
          // Просмотры — нижний правый угол (замер 10/10 px); у карточек с 0 просмотров бейджа нет.
          if (r.views) {
            expect(r.views.r, `${at}: просмотры у правого края`).toBeGreaterThanOrEqual(0);
            expect(r.views.r, `${at}: просмотры у правого края`).toBeLessThanOrEqual(16);
            expect(r.views.b, `${at}: просмотры у нижнего края`).toBeGreaterThanOrEqual(0);
            expect(r.views.b, `${at}: просмотры у нижнего края`).toBeLessThanOrEqual(16);
          }
        }
        expect(rows.filter((r) => r.views).length, `${p.name}: хотя бы у одной карточки есть бейдж просмотров`).toBeGreaterThan(0);
      });
    }
  });
}

test.describe('Значки карточек — гость', () => {
  test('/search: «поделиться» появляется при наведении на окно медиа, в верхнем углу #0a2499 @desktop @prod-safe', async ({ page }) => {
    await prepare(page);
    await openCards(page, '/search');
    const media = page.locator(MEDIA).first();
    const share = media.locator('button:has(svg.lucide-share2)');
    await expect(share, 'у гостя есть «поделиться»').toHaveCount(1);
    const groupOpacity = () => share.evaluate((b) => getComputedStyle(b.parentElement!).opacity);
    expect(await groupOpacity(), 'до наведения значки скрыты').toBe('0');

    await media.hover();
    await expect.poll(groupOpacity, { message: 'после наведения значки видны' }).toBe('1');
    const [m, s] = [await media.boundingBox(), await share.boundingBox()];
    expect(s!.y - m!.y, '«поделиться» у верхнего края окна').toBeLessThanOrEqual(22);
    expect(s!.x - m!.x, '«поделиться» в левой половине окна').toBeLessThanOrEqual(m!.width / 2);
    expect(s!.x, '«поделиться» внутри окна').toBeGreaterThanOrEqual(m!.x);
  });
});
